@Composable
private fun RatesListUiContent(
    state: RatesListUiState,
    onRefresh: () -> Unit,
    onQueryChange: (String) -> Unit,
    onCurrencyClick: (String) -> Unit,
    modifier: Modifier = Modifier,
) = Column(
